CREATE DATABASE IF NOT EXISTS smart_parking CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smart_parking;
CREATE TABLE users (user_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,phone VARCHAR(15),vehicle_number VARCHAR(20),vehicle_type ENUM('car','bike','other') DEFAULT 'car',vehicle_color VARCHAR(50),vehicle_model VARCHAR(100),rfid_uid VARCHAR(40) UNIQUE,profile_photo VARCHAR(255),registered_date DATETIME DEFAULT CURRENT_TIMESTAMP,email_verified_at DATETIME NULL,status ENUM('pending_rfid','active','blocked') DEFAULT 'pending_rfid',pass_type ENUM('normal','monthly') DEFAULT 'normal',role ENUM('user','admin') DEFAULT 'user',notification_preferences JSON);
CREATE TABLE slots (slot_id INT PRIMARY KEY,label VARCHAR(30),status ENUM('free','occupied','reserved','maintenance') DEFAULT 'free',current_user_id INT NULL,current_session INT NULL,last_updated DATETIME DEFAULT CURRENT_TIMESTAMP,gate_status ENUM('open','closed') DEFAULT 'closed',CONSTRAINT fk_slot_user FOREIGN KEY (current_user_id) REFERENCES users(user_id) ON DELETE SET NULL);
CREATE TABLE bookings (booking_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,slot_number INT NOT NULL,booking_date DATETIME NOT NULL,expected_arrival DATETIME NOT NULL,booking_expires_at DATETIME NULL,duration_hours INT NOT NULL,notes TEXT,status ENUM('pending','active','completed','cancelled','expired') DEFAULT 'pending',amount_paid DECIMAL(10,2) DEFAULT 0,payment_status ENUM('paid','unpaid') DEFAULT 'unpaid',razorpay_id VARCHAR(100),vehicle_number VARCHAR(20),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY (slot_number) REFERENCES slots(slot_id));
CREATE TABLE parking_sessions (session_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,slot_number INT NOT NULL,entry_time DATETIME NOT NULL,exit_time DATETIME NULL,registered_hours INT NOT NULL,total_hours DECIMAL(10,2),base_amount DECIMAL(10,2),overtime_amount DECIMAL(10,2),total_amount DECIMAL(10,2),payment_status ENUM('paid','unpaid') DEFAULT 'unpaid',payment_mode ENUM('cash','online') NULL,booking_id INT NULL,vehicle_photo VARCHAR(255),vehicle_number VARCHAR(20),source ENUM('walk_in','pre_booked') DEFAULT 'walk_in',overstay_notified BOOLEAN DEFAULT FALSE,FOREIGN KEY (user_id) REFERENCES users(user_id),FOREIGN KEY (slot_number) REFERENCES slots(slot_id),FOREIGN KEY (booking_id) REFERENCES bookings(booking_id));
ALTER TABLE slots ADD CONSTRAINT fk_slot_session FOREIGN KEY (current_session) REFERENCES parking_sessions(session_id) ON DELETE SET NULL;
CREATE TABLE payments (payment_id INT AUTO_INCREMENT PRIMARY KEY,session_id INT NULL,user_id INT NOT NULL,booking_id INT NULL,amount DECIMAL(10,2) NOT NULL,payment_mode VARCHAR(30) NOT NULL,payment_time DATETIME NOT NULL,razorpay_id VARCHAR(100),status ENUM('success','failed','pending') DEFAULT 'pending',FOREIGN KEY (session_id) REFERENCES parking_sessions(session_id),FOREIGN KEY (user_id) REFERENCES users(user_id),FOREIGN KEY (booking_id) REFERENCES bookings(booking_id));
CREATE TABLE fastag_accounts (fastag_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,tag_number VARCHAR(40) NOT NULL UNIQUE,vehicle_number VARCHAR(20) NOT NULL,provider_name VARCHAR(80) NOT NULL DEFAULT 'SmartPark Demo FASTag',wallet_balance DECIMAL(10,2) NOT NULL DEFAULT 500.00,status ENUM('active','blocked') NOT NULL DEFAULT 'active',linked_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE);
CREATE TABLE fastag_transactions (transaction_id BIGINT AUTO_INCREMENT PRIMARY KEY,fastag_id INT NOT NULL,payment_id INT NULL,amount DECIMAL(10,2) NOT NULL,transaction_type ENUM('debit','credit') NOT NULL,reference_number VARCHAR(100) NOT NULL UNIQUE,description VARCHAR(255),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (fastag_id) REFERENCES fastag_accounts(fastag_id) ON DELETE CASCADE,FOREIGN KEY (payment_id) REFERENCES payments(payment_id) ON DELETE SET NULL);
CREATE TABLE refunds (refund_id INT AUTO_INCREMENT PRIMARY KEY,payment_id INT NOT NULL,booking_id INT NULL,user_id INT NOT NULL,amount DECIMAL(10,2) NOT NULL,reason VARCHAR(255) NOT NULL,status ENUM('requested','approved','rejected','processed') NOT NULL DEFAULT 'requested',admin_note VARCHAR(255),provider_reference VARCHAR(100),processed_by INT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,processed_at DATETIME NULL,FOREIGN KEY (payment_id) REFERENCES payments(payment_id),FOREIGN KEY (booking_id) REFERENCES bookings(booking_id),FOREIGN KEY (user_id) REFERENCES users(user_id),FOREIGN KEY (processed_by) REFERENCES users(user_id));
CREATE TABLE notifications (notif_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,type VARCHAR(50) NOT NULL,message TEXT NOT NULL,is_read BOOLEAN DEFAULT FALSE,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE);
CREATE TABLE auth_tokens (token_id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,email VARCHAR(150) NOT NULL,purpose VARCHAR(40) NOT NULL,token_hash CHAR(64) NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX idx_auth_tokens_lookup (email,purpose,expires_at),FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE);
CREATE TABLE rates (rate_id INT PRIMARY KEY,normal_rate DECIMAL(10,2) DEFAULT 20.00,overtime_rate DECIMAL(10,2) DEFAULT 40.00,peak_rate DECIMAL(10,2) DEFAULT 30.00,peak_start TIME,peak_end TIME,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE hardware_events (event_id BIGINT AUTO_INCREMENT PRIMARY KEY,event_type VARCHAR(50) NOT NULL,slot_number INT NULL,uid VARCHAR(40),payload JSON NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,INDEX idx_hardware_events_created_at (created_at),INDEX idx_hardware_events_slot (slot_number));
